    /// <param name="httpClientFactory">リポジトリ生成時に使う HttpClient を返すファクトリ</param>
    public static IServiceCollection AddGeneratedHttpRemoteRepositories(
        this IServiceCollection services,
        Func<IServiceProvider, HttpClient> httpClientFactory
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(httpClientFactory);

        services.AddScoped<IDocumentRemoteRepository>(provider => new HttpDocumentRemoteRepository(
            httpClientFactory(provider)
        ));
        services.AddScoped<IDocumentNoteRemoteRepository>(provider => new HttpDocumentNoteRemoteRepository(
            httpClientFactory(provider)
        ));

        return services;
    }
}

/// <summary>
/// DB を使わずエンティティをメモリ上に保持するインメモリデータストア（DI で Singleton 共有）。
/// </summary>
/// <remarks>
/// <para>
/// エンティティ型ごとに「主キー → スナップショット複製」の辞書を持つ。書き込み（保存・削除）と読み取り（取得・クエリ）は
/// 内部で常に <see cref="EntityBase.Clone"/> による複製を介するため、返却したエンティティを呼び出し側で変更しても
/// ストアの内容は変化しない（実 DB の値渡し意味論に合わせる）。すべての操作は <c>lock</c> で直列化しスレッド安全にする。
/// </para>
/// <para>
/// 主キーは <see cref="EntitySaveMetadata.KeyProperty"/> から取り出し、値オブジェクトは内包値へ開いて辞書キーにする
/// （値等価で突き合わせるため）。
/// </para>
/// </remarks>
public sealed class InMemoryDataStore
{
    private readonly object _gate = new();
    private readonly Dictionary<Type, Dictionary<object, EntityBase>> _tables = new();

    /// <summary>指定型のテーブル（主キー → スナップショット）を取得する（無ければ生成する）。呼び出しは lock 済みであること</summary>
    private Dictionary<object, EntityBase> Table(Type entityType)
    {
        if (!_tables.TryGetValue(entityType, out var table))
        {
            table = new Dictionary<object, EntityBase>();
            _tables[entityType] = table;
        }

        return table;
    }

    /// <summary>エンティティの主キー値を辞書キーへ正規化する（値オブジェクトは内包値へ開く。null は不可）</summary>
    internal static object KeyOf(EntityBase entity)
    {
        var metadata = EntitySaveMetadata.For(entity.GetType());
        var raw = metadata.KeyProperty.GetValue(entity);

        return raw
            ?? throw new InvalidOperationException(
                $"{entity.GetType().Name} の主キーが null です。インメモリ保存には主キー値が必要です。"
            );
    }

    /// <summary>指定型の全スナップショットを（複製して）取得する</summary>
    /// <remarks>返却複製は無制限バイナリ列を「未取得状態」へ落とす（実 DB の SELECT 除外と揃える。ストアの実体は保持）</remarks>
    public IReadOnlyList<TEntity> Snapshot<TEntity>()
        where TEntity : EntityBase, new()
    {
        lock (_gate)
        {
            return Table(typeof(TEntity))
                .Values.Select(entity =>
                {
                    var clone = (TEntity)entity.Clone();
                    UnboundedBinaryColumns.StripExcluded(clone);
                    return clone;
                })
                .ToList();
        }
    }

    /// <summary>指定型・主キーのスナップショットを（複製して）取得する（該当なしは null）</summary>
    /// <remarks>返却複製は無制限バイナリ列を「未取得状態」へ落とす（実 DB の SELECT 除外と揃える。ストアの実体は保持）</remarks>
    public TEntity? Find<TEntity>(object key)
        where TEntity : EntityBase, new()
    {
        lock (_gate)
        {
            if (!Table(typeof(TEntity)).TryGetValue(key, out var entity))
            {
                return null;
            }

            var clone = (TEntity)entity.Clone();
            UnboundedBinaryColumns.StripExcluded(clone);
            return clone;
        }
    }

    /// <summary>指定型・主キーの生スナップショット（複製なし）を取得する。Include のキー突き合わせなど内部走査で使う。呼び出しは lock 済みであること</summary>
    private EntityBase? FindRaw(Type entityType, object key) =>
        Table(entityType).TryGetValue(key, out var entity) ? entity : null;

    /// <summary>指定型の生スナップショット一覧（複製なし）を取得する。クエリ実行器の内部走査で使う。呼び出しは lock 済みであること</summary>
    private IReadOnlyList<EntityBase> RawAll(Type entityType) => Table(entityType).Values.ToList();

    /// <summary>指定型の生スナップショット一覧（複製なし）を取得する。実行器へ複製前のスナップショットを渡すために lock 内で使う</summary>
    internal IReadOnlyList<EntityBase> RawSnapshotUnlocked(Type entityType) => RawAll(entityType);

    /// <summary>ストア全体で任意の読み取り走査を lock 下で実行する（Include のキー突き合わせで複数テーブルを横断するため）</summary>
    internal TResult Read<TResult>(Func<InMemoryReadScope, TResult> reader)
    {
        lock (_gate)
        {
            return reader(new InMemoryReadScope(this));
        }
    }

    /// <summary>スナップショット（複製）を格納する（追加・更新共通。既存キーは置換）</summary>
    internal void Put(EntityBase entity)
    {
        lock (_gate)
        {
            var snapshot = entity.Clone();
            snapshot.MarkUnchanged();
            Table(entity.GetType())[KeyOf(entity)] = snapshot;
        }
    }

    /// <summary>指定型・主キーのスナップショットを削除する（該当ありで true）</summary>
    internal bool Remove(Type entityType, object key)
    {
        lock (_gate)
        {
            return Table(entityType).Remove(key);
        }
    }

    /// <summary>
    /// 指定型・主キーの列値を strip なしで読み取る（無制限バイナリ列の Stream アクセサ用）。
    /// ストア実体の生の値を返す（読み取り複製の strip を経由しない＝除外列の実データが取れる）。
    /// </summary>
    internal object? ReadColumnValue(
        Type entityType,
        object key,
        PropertyInfo column,
        out bool rowExists
    )
    {
        lock (_gate)
        {
            var entity = FindRaw(entityType, key);
            rowExists = entity is not null;
            return entity is null ? null : column.GetValue(entity);
        }
    }

    /// <summary>
    /// 指定型・主キーの列値を書き換える（無制限バイナリ列の Stream アクセサ用・該当ありで true）。
    /// ストア実体を直接書き換えず、複製を更新して差し戻す（既存の Clone/Put 意味論に従う）。
    /// </summary>
    internal bool WriteColumnValue(Type entityType, object key, PropertyInfo column, object? value)
    {
        lock (_gate)
        {
            var entity = FindRaw(entityType, key);

            if (entity is null)
            {
                return false;
            }

            var clone = entity.Clone();
            column.SetValue(clone, value);
            clone.MarkUnchanged();
            Table(entityType)[key] = clone;
            return true;
        }
    }

    /// <summary>複数の書き込み（追加・更新・削除）を 1 つの lock 下でまとめて適用する（グラフ保存の原子性を保つ）</summary>
    internal TResult Write<TResult>(Func<InMemoryWriteScope, TResult> writer)
    {
        lock (_gate)
        {
            return writer(new InMemoryWriteScope(this));
        }
    }

    /// <summary>全テーブルを空にする（テストのリセット用）</summary>
    public void Clear()
    {
        lock (_gate)
        {
            _tables.Clear();
        }
    }

    /// <summary>lock 下で複数テーブルを横断読み取りするためのスコープ（Include のキー突き合わせで使う）</summary>
    internal readonly struct InMemoryReadScope(InMemoryDataStore store)
    {
        /// <summary>指定型の生スナップショット一覧（複製なし）</summary>
        public IReadOnlyList<EntityBase> All(Type entityType) => store.RawAll(entityType);

        /// <summary>指定型・主キーの生スナップショット（複製なし。該当なしは null）</summary>
        public EntityBase? Find(Type entityType, object key) => store.FindRaw(entityType, key);
    }

    /// <summary>lock 下でグラフ全体の書き込みを適用するためのスコープ</summary>
    internal readonly struct InMemoryWriteScope(InMemoryDataStore store)
    {
        /// <summary>スナップショットを格納する（追加・更新）。lock 済み前提のため内部辞書へ直接反映する</summary>
        public void Put(EntityBase entity)
        {
            var snapshot = entity.Clone();
            snapshot.MarkUnchanged();
            store.Table(entity.GetType())[KeyOf(entity)] = snapshot;
        }

        /// <summary>指定型・主キーのスナップショットを削除する（該当ありで true）</summary>
        public bool Remove(Type entityType, object key) => store.Table(entityType).Remove(key);

        /// <summary>指定型・主キーのスナップショットが存在するか</summary>
        public bool Exists(Type entityType, object key) => store.Table(entityType).ContainsKey(key);

        /// <summary>指定型の生スナップショット一覧（複製なし）。カスケード削除の子孫走査で使う</summary>
        public IReadOnlyList<EntityBase> All(Type entityType) => store.RawAll(entityType);
    }
}

/// <summary>
/// <see cref="ISqlQueryExecutor{TEntity}"/> のインメモリ実装。<see cref="SqlQueryPlan{TEntity}"/> の述語・並び順・
/// ページングを LINQ-to-Objects で評価し、Include ツリーは FK メタデータからナビゲーションを復元して装着する。
/// </summary>
/// <remarks>
/// 述語（<see cref="LambdaExpression"/>）は <see cref="LambdaExpression.Compile"/> でデリゲート化して評価する
/// （SQL 翻訳は行わない）。返却するエンティティは常にストアのスナップショットを複製したもので、Include で装着した
/// ナビゲーションも複製済みの子/親を指す（呼び出し側の変更がストアへ波及しない）。
/// </remarks>
internal sealed class InMemoryQueryExecutor<TEntity>(InMemoryDataStore store)
    : ISqlQueryExecutor<TEntity>
    where TEntity : EntityBase, new()
{
    private readonly InMemoryDataStore _store = store;

    /// <summary>述語（AND 結合）・並び順・Skip/Take を適用した結果を、Include 装着済み複製として返す</summary>
    public Task<IReadOnlyList<TEntity>> ToListAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        var result = _store.Read(scope =>
        {
            var matched = ApplyOrderingAndPaging(FilterRaw(plan), plan);
            // 複製してから Include を装着する（ストアの実体を書き換えないため）。返却複製は既定で無制限バイナリ列を未取得状態へ落とす
            // （WithUnboundedBinary 指定時は strip せず完全クローンを返す＝除外列も取得できる。Include なしは終端でガード済み）
            var cloned = matched
                .Select(entity =>
                {
                    var clone = (TEntity)entity.Clone();

                    if (!plan.WithUnboundedBinary)
                    {
                        UnboundedBinaryColumns.StripExcluded(clone);
                    }

                    return clone;
                })
                .ToList();

            foreach (var entity in cloned)
            {
                IncludeAttacher.Attach(entity, plan.Includes, scope);
            }

            return (IReadOnlyList<TEntity>)cloned;
        });

        return Task.FromResult(result);
    }

    /// <summary>述語・並び順・Skip/Take を適用した複製に射影を適用して一覧を返す（実 DB の列刈り込みと結果同値）</summary>
    /// <remarks>
    /// Include なし・列参照のみのセレクタなら「完全クローンから射影」する（無制限バイナリ列も参照可能＝実 DB が
    /// 参照列を SELECT に含めるのと同じパリティ）。Include 併用時や列参照を抽出できない場合は、従来経路
    /// （ToListAsync と同じく無制限バイナリ列を strip した複製）から射影する（実 DB のフォールバックと同じパリティ）。
    /// </remarks>
    public Task<IReadOnlyList<TResult>> ToProjectionListAsync<TResult>(
        SqlQueryPlan<TEntity> plan,
        Expression<Func<TEntity, TResult>> selector,
        CancellationToken cancellationToken
    )
    {
        var project = selector.Compile();

        // Include なし・列参照のみなら完全クローンから射影（除外列も参照できる）。不能時は strip 済みから射影
        var prunable =
            plan.Includes.Count == 0
            && ProjectionColumnCollector.TryCollect(selector, out var referenced)
            && EntitySaveMetadata.For(typeof(TEntity)).ResolveProjectionColumns(referenced) is not null;

        var result = _store.Read(scope =>
        {
            var matched = ApplyOrderingAndPaging(FilterRaw(plan), plan);
            var projected = new List<TResult>(matched.Count);

            foreach (var entity in matched)
            {
                // ストア実体と byte[] 等を共有しないよう必ず複製してから射影する
                var clone = (TEntity)entity.Clone();

                if (!prunable)
                {
                    // 従来経路（ToListAsync）と同一パリティ: 無制限バイナリ列を strip し、Include を装着してから射影する
                    UnboundedBinaryColumns.StripExcluded(clone);
                    IncludeAttacher.Attach(clone, plan.Includes, scope);
                }

                projected.Add(project(clone));
            }

            return (IReadOnlyList<TResult>)projected;
        });

        return Task.FromResult(result);
    }

    /// <summary>先頭 1 件を Include 装着済み複製として返す（該当なしは null）</summary>
    public Task<TEntity?> FirstOrDefaultAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        var result = _store.Read(scope =>
        {
            var first = ApplyOrderingAndPaging(FilterRaw(plan), plan).FirstOrDefault();

            if (first is null)
            {
                return null;
            }

            var cloned = (TEntity)first.Clone();

            // 既定は無制限バイナリ列を未取得状態へ落とす。WithUnboundedBinary 指定時は strip せず完全クローンを返す
            if (!plan.WithUnboundedBinary)
            {
                UnboundedBinaryColumns.StripExcluded(cloned);
            }

            IncludeAttacher.Attach(cloned, plan.Includes, scope);
            return cloned;
        });

        return Task.FromResult(result);
    }

    /// <summary>条件に一致する件数を返す（並び順・ページング・Include は関与しない）</summary>
    public Task<int> CountAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken) =>
        Task.FromResult(_store.Read(_ => FilterRaw(plan).Count()));

    /// <summary>条件に一致する行が存在するかを返す</summary>
    public Task<bool> AnyAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken) =>
        Task.FromResult(_store.Read(_ => FilterRaw(plan).Any()));

    /// <summary>条件に一致する行を削除する。cascadeDelete=true で子孫も FK 連鎖で削除する</summary>
    public Task<int> ExecuteDeleteAsync(
        SqlQueryPlan<TEntity> plan,
        bool cascadeDelete,
        CancellationToken cancellationToken
    )
    {
        var rows = _store.Write(scope =>
        {
            // 削除対象は評価時点のスナップショット（複製前）の主キーで確定する
            var targets = FilterRaw(plan).ToList();
            var removed = 0;

            foreach (var target in targets)
            {
                if (cascadeDelete)
                {
                    removed += InMemoryCascade.DeleteDescendants(target, scope);
                }

                if (scope.Remove(typeof(TEntity), InMemoryDataStore.KeyOf(target)))
                {
                    removed++;
                }
            }

            return removed;
        });

        return Task.FromResult(rows);
    }

    /// <summary>ストアの生スナップショットに述語（AND 結合）を適用して絞り込む（複製前・列挙のみ）</summary>
    private IEnumerable<EntityBase> FilterRaw(SqlQueryPlan<TEntity> plan)
    {
        IEnumerable<TEntity> query = _store.RawSnapshotUnlocked(typeof(TEntity)).Cast<TEntity>();

        foreach (var predicate in plan.Predicates)
        {
            var compiled = (Func<TEntity, bool>)predicate.Compile();
            query = query.Where(compiled);
        }

        return query;
    }

    /// <summary>並び順（指定順に安定ソート）と Skip/Take を適用する</summary>
    private static IReadOnlyList<EntityBase> ApplyOrderingAndPaging(
        IEnumerable<EntityBase> source,
        SqlQueryPlan<TEntity> plan
    )
    {
        var typed = source.Cast<TEntity>();
        IOrderedEnumerable<TEntity>? ordered = null;

        foreach (var ordering in plan.Orderings)
        {
            var keySelector = (Func<TEntity, object?>)ordering.KeySelector.Compile();

            if (ordered is null)
            {
                ordered = ordering.Descending
                    ? typed.OrderByDescending(keySelector)
                    : typed.OrderBy(keySelector);
            }
            else
            {
                ordered = ordering.Descending
                    ? ordered.ThenByDescending(keySelector)
                    : ordered.ThenBy(keySelector);
            }
        }

        IEnumerable<TEntity> result = ordered ?? typed;

        if (plan.Skip is { } skip)
        {
            result = result.Skip(skip);
        }

        if (plan.Take is { } take)
        {
            result = result.Take(take);
        }

        return result.Cast<EntityBase>().ToList();
    }
}

/// <summary>Include ツリーに沿って FK メタデータからナビゲーション（子集合・親参照）を復元し、複製グラフへ装着する</summary>
internal static class IncludeAttacher
{
    /// <summary>指定エンティティ（複製）へ Include ツリー分のナビゲーションを再帰的に装着する</summary>
    public static void Attach(
        EntityBase entity,
        IReadOnlyList<IncludeNode> includes,
        InMemoryDataStore.InMemoryReadScope scope
    )
    {
        foreach (var node in includes)
        {
            var attribute =
                node.Property.GetCustomAttribute<NavigationReferenceAttribute>()
                ?? throw new InvalidOperationException(
                    $"{node.Property.Name} は [NavigationReference] を持つナビゲーションではありません。"
                );

            var metadata = EntitySaveMetadata.For(entity.GetType());

            if (attribute.IsCollection || !attribute.IsParentReference)
            {
                AttachChildren(entity, node, attribute, metadata, scope);
            }
            else
            {
                AttachParent(entity, node, attribute, metadata, scope);
            }
        }
    }

    /// <summary>コレクション/子方向の単一参照ナビゲーションを、FK が親キーへ一致する子で埋める</summary>
    private static void AttachChildren(
        EntityBase parent,
        IncludeNode node,
        NavigationReferenceAttribute attribute,
        EntitySaveMetadata parentMetadata,
        InMemoryDataStore.InMemoryReadScope scope
    )
    {
        var childType = attribute.IsCollection
            ? node.Property.PropertyType.GetGenericArguments()[0]
            : node.Property.PropertyType;
        var childMetadata = EntitySaveMetadata.For(childType);

        var parentKey = ColumnValue(parent, attribute.PrincipalColumn, parentMetadata);
        var matched = new List<EntityBase>();

        foreach (var child in scope.All(childType))
        {
            var fk = ColumnValue(child, attribute.DependentColumn, childMetadata);

            if (parentKey is not null && Equals(fk, parentKey))
            {
                var clonedChild = child.Clone();
                UnboundedBinaryColumns.StripExcluded(clonedChild);
                Attach(clonedChild, node.Children, scope);
                matched.Add(clonedChild);
            }
        }

        if (attribute.IsCollection)
        {
            // ICollection<childType> の具象 List を生成して詰める
            var listType = typeof(List<>).MakeGenericType(childType);
            var list = (System.Collections.IList)Activator.CreateInstance(listType)!;

            foreach (var child in matched)
            {
                list.Add(child);
            }

            node.Property.SetValue(parent, list);
        }
        else
        {
            node.Property.SetValue(parent, matched.Count > 0 ? matched[0] : null);
        }
    }

    /// <summary>親参照ナビゲーションを、自身の FK が指す親で埋める</summary>
    private static void AttachParent(
        EntityBase dependent,
        IncludeNode node,
        NavigationReferenceAttribute attribute,
        EntitySaveMetadata dependentMetadata,
        InMemoryDataStore.InMemoryReadScope scope
    )
    {
        var parentType = node.Property.PropertyType;
        var parentMetadata = EntitySaveMetadata.For(parentType);

        var fk = ColumnValue(dependent, attribute.DependentColumn, dependentMetadata);

        if (fk is null)
        {
            node.Property.SetValue(dependent, null);
            return;
        }

        foreach (var candidate in scope.All(parentType))
        {
            var principal = ColumnValue(candidate, attribute.PrincipalColumn, parentMetadata);

            if (Equals(principal, fk))
            {
                var clonedParent = candidate.Clone();
                UnboundedBinaryColumns.StripExcluded(clonedParent);
                Attach(clonedParent, node.Children, scope);
                node.Property.SetValue(dependent, clonedParent);
                return;
            }
        }

        node.Property.SetValue(dependent, null);
    }

    /// <summary>指定カラムの値をエンティティから取り出す（値オブジェクトは内包値へ開く）</summary>
    private static object? ColumnValue(
        EntityBase entity,
        string columnName,
        EntitySaveMetadata metadata
    )
    {
        if (!metadata.PropertyByColumn.TryGetValue(columnName, out var property))
        {
            throw new InvalidOperationException(
                $"{entity.GetType().Name} にカラム {columnName} に対応するプロパティがありません。"
            );
        }

        var value = property.GetValue(entity);
        return value;
    }
}

/// <summary>インメモリ Repository のカスケード保存・削除（FK メタデータ由来の子ナビゲーション走査）</summary>
internal static class InMemoryCascade
{
    /// <summary>カスケード対象の子エンティティを列挙する（null は除外）</summary>
    public static IEnumerable<EntityBase> EnumerateChildren(EntityBase entity)
    {
        foreach (var navigation in EntitySaveMetadata.For(entity.GetType()).CascadeNavigations)
        {
            var value = navigation.Property.GetValue(entity);

            if (value is null)
            {
                continue;
            }

            if (navigation.IsCollection)
            {
                if (value is IEnumerable<EntityBase> children)
                {
                    foreach (var child in children)
                    {
                        if (child is not null)
                        {
                            yield return child;
                        }
                    }
                }
            }
            else if (value is EntityBase child)
            {
                yield return child;
            }
        }
    }

    /// <summary>RowState 駆動でグラフを保存し、書き込んだ件数を返す（QuickER の EntityGraphSaver と同じ意味論）</summary>
    /// <remarks>
    /// IsRemoved は子から削除し自身を削除、IsAdded は挿入、IsUpdated は更新（対象なしは
    /// insertWhenUpdateMissing で挿入 or 競合例外）。追加・更新は自身を先に、削除は子を先に処理する。
    /// <paramref name="hooks"/> 指定時は <see cref="SaveHookSession.Skipped"/> に含まれるノードの Put/Remove を抑止し、
    /// 実際に実行した操作を <paramref name="records"/>（実行順）へ記録する（After の発火順・操作の確定に使う）。
    /// </remarks>
    public static int Save(
        EntityBase entity,
        InMemoryDataStore.InMemoryWriteScope scope,
        bool cascadeSave,
        bool cascadeDelete,
        bool insertWhenUpdateMissing,
        SaveHookSession? hooks = null,
        List<(EntityBase Entity, SaveOperation Operation)>? records = null
    )
    {
        if (!EntityGraphSaver.HasChanges(entity, cascadeSave))
        {
            return 0;
        }

        var rows = 0;
        var entityType = entity.GetType();
        var key = InMemoryDataStore.KeyOf(entity);

        if (entity.IsRemoved)
        {
            if (cascadeDelete)
            {
                foreach (var child in EnumerateChildren(entity))
                {
                    rows += DeleteGraph(child, scope, hooks, records);
                }
            }

            // Before(Delete) が false（スキップ）なら自身の削除だけ行わない（子は上で削除済み＝自身は残る）
            if (hooks is not null && hooks.Skipped.Contains(entity))
            {
                return rows;
            }

            if (scope.Remove(entityType, key))
            {
                rows++;
            }

            records?.Add((entity, SaveOperation.Delete));
            return rows;
        }

        if (entity.IsAdded)
        {
            // スキップされていなければ挿入する（スキップ時も子カスケードは続行する）
            if (hooks is null || !hooks.Skipped.Contains(entity))
            {
                scope.Put(entity);
                rows++;
                records?.Add((entity, SaveOperation.Insert));
            }
        }
        else if (entity.IsUpdated)
        {
            if (hooks is null || !hooks.Skipped.Contains(entity))
            {
                // 実 DB のグラフ更新と同じく、無制限バイナリ列に値が残ったままの更新は弾く
                UnboundedBinaryColumns.ThrowIfExcludedAssigned(entity);

                if (scope.Exists(entityType, key))
                {
                    scope.Put(entity);
                    rows++;
                    records?.Add((entity, SaveOperation.Update));
                }
                else if (insertWhenUpdateMissing)
                {
                    // 更新対象がなく INSERT へ切り替えた＝After は実操作 Insert で発火する
                    scope.Put(entity);
                    rows++;
                    records?.Add((entity, SaveOperation.Insert));
                }
                else
                {
                    throw new SaveConflictException(
                        $"更新対象のレコードが見つかりませんでした（{entityType.Name}、キー {key}）。他のユーザーに削除された可能性があります。"
                    );
                }
            }
        }

        if (cascadeSave)
        {
            foreach (var child in EnumerateChildren(entity))
            {
                rows += Save(
                    child,
                    scope,
                    cascadeSave,
                    cascadeDelete,
                    insertWhenUpdateMissing,
                    hooks,
                    records
                );
            }
        }

        return rows;
    }

    /// <summary>フェーズ 1: グラフを <see cref="Save"/> と同一順序で走査し、各操作の直前フック（Before）を発火してスキップ集合を作る（lock 外・async）</summary>
    /// <remarks>Before は RowState 由来の操作で発火する（<c>insertWhenUpdateMissing</c> の Insert 切替でも Update で 1 回）。実操作の確定は保存フェーズが行う。</remarks>
    public static async Task InvokeBeforeGraphAsync(
        EntityBase entity,
        SaveHookSession hooks,
        bool cascadeSave,
        bool cascadeDelete,
        CancellationToken cancellationToken
    )
    {
        if (!EntityGraphSaver.HasChanges(entity, cascadeSave))
        {
            return;
        }

        if (entity.IsRemoved)
        {
            // 削除は子から順（Save / DeleteGraph と同一順序）に Before を発火する
            if (cascadeDelete)
            {
                foreach (var child in EnumerateChildren(entity))
                {
                    await InvokeBeforeDeleteGraphAsync(child, hooks, cancellationToken);
                }
            }

            if (!await hooks.InvokeBeforeAsync(entity, SaveOperation.Delete, cancellationToken))
            {
                hooks.Skip(entity);
            }

            return;
        }

        if (entity.IsAdded)
        {
            if (!await hooks.InvokeBeforeAsync(entity, SaveOperation.Insert, cancellationToken))
            {
                hooks.Skip(entity);
            }
        }
        else if (entity.IsUpdated)
        {
            if (!await hooks.InvokeBeforeAsync(entity, SaveOperation.Update, cancellationToken))
            {
                hooks.Skip(entity);
            }
        }

        if (cascadeSave)
        {
            foreach (var child in EnumerateChildren(entity))
            {
                await InvokeBeforeGraphAsync(
                    child,
                    hooks,
                    cascadeSave,
                    cascadeDelete,
                    cancellationToken
                );
            }
        }
    }

    /// <summary>サブツリー削除の Before を子から順に発火する（<see cref="DeleteGraph"/> と同一順序）</summary>
    private static async Task InvokeBeforeDeleteGraphAsync(
        EntityBase entity,
        SaveHookSession hooks,
        CancellationToken cancellationToken
    )
    {
        foreach (var child in EnumerateChildren(entity))
        {
            await InvokeBeforeDeleteGraphAsync(child, hooks, cancellationToken);
        }

        if (!await hooks.InvokeBeforeAsync(entity, SaveOperation.Delete, cancellationToken))
        {
            hooks.Skip(entity);
        }
    }

    /// <summary>サブツリーを子から順に削除する（状態に関わらず削除。<paramref name="hooks"/> 指定時はスキップ行を残し、実行した削除を <paramref name="records"/> へ記録）</summary>
    private static int DeleteGraph(
        EntityBase entity,
        InMemoryDataStore.InMemoryWriteScope scope,
        SaveHookSession? hooks = null,
        List<(EntityBase Entity, SaveOperation Operation)>? records = null
    )
    {
        var rows = 0;

        foreach (var child in EnumerateChildren(entity))
        {
            rows += DeleteGraph(child, scope, hooks, records);
        }

        // Before(Delete) が false（スキップ）なら自身の削除を行わない（子は既に削除済み）
        if (hooks is not null && hooks.Skipped.Contains(entity))
        {
            return rows;
        }

        if (scope.Remove(entity.GetType(), InMemoryDataStore.KeyOf(entity)))
        {
            rows++;
        }

        records?.Add((entity, SaveOperation.Delete));
        return rows;
    }

    /// <summary>ロード済みグラフを持たない ExecuteDelete 用に、ストア上の子孫を FK 連鎖で削除する（子→孫を先に削除）</summary>
    /// <remarks>
    /// カスケードナビゲーション（FK メタデータ）を辿り、DependentColumn が親の PrincipalColumn 値に一致する子を
    /// ストアから探して削除する。循環するカスケード（自己参照等）は固定走査で表現できないため未対応とする。
    /// </remarks>
    public static int DeleteDescendants(
        EntityBase root,
        InMemoryDataStore.InMemoryWriteScope scope
    ) => DeleteDescendants(root, scope, new HashSet<Type> { root.GetType() });

    private static int DeleteDescendants(
        EntityBase parent,
        InMemoryDataStore.InMemoryWriteScope scope,
        HashSet<Type> visited
    )
    {
        var rows = 0;
        var parentMetadata = EntitySaveMetadata.For(parent.GetType());

        foreach (var navigation in parentMetadata.CascadeNavigations)
        {
            if (!visited.Add(navigation.ChildType))
            {
                throw new NotSupportedException(
                    $"循環するカスケード（{navigation.ChildType.Name}）は ExecuteDeleteAsync では未対応です。グラフをロードして SaveAsync を使うか、ロード済みグラフに対して SaveAsync を使ってください。"
                );
            }

            var childMetadata = EntitySaveMetadata.For(navigation.ChildType);
            var parentKey = ColumnValue(parent, navigation.PrincipalColumn, parentMetadata);

            // 子スナップショットは削除中に列挙が壊れないよう先に確定してから削除する
            var children = scope
                .All(navigation.ChildType)
                .Where(child =>
                    parentKey is not null
                    && Equals(
                        ColumnValue(child, navigation.DependentColumn, childMetadata),
                        parentKey
                    )
                )
                .ToList();

            foreach (var child in children)
            {
                // 先に孫以下を削除してから子を削除する（FK 整合）
                rows += DeleteDescendants(child, scope, visited);

                if (scope.Remove(navigation.ChildType, InMemoryDataStore.KeyOf(child)))
                {
                    rows++;
                }
            }

            visited.Remove(navigation.ChildType);
        }

        return rows;
    }

    /// <summary>指定カラムの値をエンティティから取り出す（値オブジェクトは内包値へ開く）</summary>
    private static object? ColumnValue(
        EntityBase entity,
        string columnName,
        EntitySaveMetadata metadata
    )
    {
        if (!metadata.PropertyByColumn.TryGetValue(columnName, out var property))
        {
            throw new InvalidOperationException(
                $"{entity.GetType().Name} にカラム {columnName} に対応するプロパティがありません。"
            );
        }

        var value = property.GetValue(entity);
        return value;
    }
}

/// <summary>メモリ上のデータストアで CRUD を実装するインメモリ Repository 基底クラス（方言非依存・実 DB 不要）</summary>
/// <remarks>
/// <para>
/// 取得系（GetById/GetAll/Query）は常にストアのスナップショットを複製して返し、RowState=Unchanged にする
/// （返却エンティティを変更してもストアは不変）。保存系（Insert/Update/Delete/Save）はスナップショットを差し替える。
/// 生 SQL 系（QueryBySql/ExecuteSql/ExecuteScalarSql）はインメモリでは実行できないため <see cref="NotSupportedException"/> を投げる。
/// </para>
/// </remarks>
public abstract partial class InMemoryRepository<TEntity, TKey>(
    InMemoryDataStore store,
    ISaveHookRegistry? saveHooks = null
) : IRepository<TEntity, TKey>
    where TEntity : EntityBase, new()
{
    /// <summary>スナップショットを保持するデータストア（DI で共有）</summary>
    protected InMemoryDataStore Store { get; } = store;

    /// <summary>Save フックのレジストリ（未指定＝null＝フックなしで完全 no-op）</summary>
    private readonly ISaveHookRegistry? _saveHooks = saveHooks;

    private const string RawSqlNotSupported =
        "インメモリ Repository は生 SQL を実行できません。実 DB の Repository へ切り替えてください。";

    /// <summary>主キーによる単一エンティティ取得（該当なしは null）</summary>
    public Task<TEntity?> GetByIdAsync(TKey id, CancellationToken cancellationToken = default) =>
        Task.FromResult(Store.Find<TEntity>(NormalizeKey(id)));

    /// <summary>全エンティティ取得</summary>
    public Task<IReadOnlyList<TEntity>> GetAllAsync(CancellationToken cancellationToken = default) =>
        Task.FromResult(Store.Snapshot<TEntity>());

    /// <summary>エンティティ追加</summary>
    public Task InsertAsync(TEntity entity, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(entity);
        Store.Put(entity);
        entity.MarkUnchanged();
        return Task.CompletedTask;
    }

    /// <summary>エンティティのコレクションを一括追加する</summary>
    public Task<int> BulkInsertAsync(
        IEnumerable<TEntity> entities,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);
        var count = 0;

        foreach (var entity in entities)
        {
            if (entity is null)
            {
                continue;
            }

            Store.Put(entity);
            entity.MarkUnchanged();
            count++;
        }

        return Task.FromResult(count);
    }

    /// <summary>エンティティ更新（更新対象ありで true）</summary>
    public Task<bool> UpdateAsync(TEntity entity, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(entity);

        // 実 DB と同じく、無制限バイナリ列に値が残ったままの更新は弾く（BindUpdateParameters を通らないため個別に）
        UnboundedBinaryColumns.ThrowIfExcludedAssigned(entity);

        var updated = Store.Write(scope =>
        {
            var key = InMemoryDataStore.KeyOf(entity);

            if (!scope.Exists(typeof(TEntity), key))
            {
                return false;
            }

            scope.Put(entity);
            return true;
        });

        if (updated)
        {
            entity.MarkUnchanged();
        }

        return Task.FromResult(updated);
    }

    /// <summary>主キーによるエンティティ削除（削除対象ありで true）</summary>
    public Task<bool> DeleteAsync(TKey id, CancellationToken cancellationToken = default) =>
        Task.FromResult(Store.Remove(typeof(TEntity), NormalizeKey(id)));

    /// <summary>検索条件・並び順・Include をチェーン指定して取得するクエリを開始する</summary>
    public SqlQuery<TEntity> Query() => new(new InMemoryQueryExecutor<TEntity>(Store));

    /// <summary>
    /// 無制限バイナリ列（除外列）を主キー指定で宛先ストリームへ読み出す（実 DB のストリーミングに対する
    /// インメモリ・パリティ）。ストア実体の生の値（strip なし）を MemoryStream 経由で書き出す。
    /// 行なし・列 NULL（未設定含む）は <c>false</c>、データを書いた場合は <c>true</c> を返す。
    /// </summary>
    protected async Task<bool> ReadUnboundedBinaryColumnAsync(
        string propertyName,
        TKey id,
        Stream destination,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(destination);

        var column = EntitySaveMetadata.For(typeof(TEntity)).ColumnByPropertyName(propertyName);
        var value = Store.ReadColumnValue(typeof(TEntity), NormalizeKey(id), column, out var rowExists);

        if (!rowExists)
        {
            return false;
        }

        if (value is not byte[] bytes)
        {
            // 列 NULL（または未設定）は何も書かない
            return false;
        }

        await destination.WriteAsync(bytes, cancellationToken);
        return true;
    }

    /// <summary>
    /// 無制限バイナリ列（除外列）を主キー指定でストリームから書き込む（インメモリ・パリティ）。<paramref name="source"/>
    /// が <c>null</c> のとき列を NULL に設定する。<c>CanSeek</c> でない Stream は <paramref name="length"/> が必須。
    /// ストア実体は直接書き換えず複製を差し戻す。更新した場合は <c>true</c>、該当行なしは <c>false</c> を返す。
    /// </summary>
    protected async Task<bool> WriteUnboundedBinaryColumnAsync(
        string propertyName,
        TKey id,
        Stream? source,
        long? length = null,
        CancellationToken cancellationToken = default
    )
    {
        var column = EntitySaveMetadata.For(typeof(TEntity)).ColumnByPropertyName(propertyName);
        object? stored;

        if (source is null)
        {
            stored = null;
        }
        else
        {
            // CanSeek/length の契約検証は実 DB と揃える（方言中立パリティ）
            _ = UnboundedBinaryColumns.ResolveWriteLength(source, length);

            // インメモリは実 DB のストリーミングを持たないため全読みして byte[] 化する（契約・意味論は同一）
            using var buffer = new MemoryStream();
            await source.CopyToAsync(
                buffer,
                UnboundedBinaryColumns.StreamCopyBufferSize,
                cancellationToken
            );
            var bytes = buffer.ToArray();
            stored = bytes;
        }

        return Store.WriteColumnValue(typeof(TEntity), NormalizeKey(id), column, stored);
    }

    /// <summary>RowState に従ってグラフを保存する（既定で子をカスケード）</summary>
    /// <remarks>
    /// Save フック登録があるときは 3 フェーズで実行する: (1) lock 外でグラフを走査し Before を発火してスキップ集合を作る、
    /// (2) lock 内でスキップを適用して保存し実行した (entity, 操作) を記録する、(3) lock 外で実行順に After を発火する。
    /// After は「コミット前」を擬似する（インメモリは実トランザクションを持たないため、After が例外を投げてもストア変更は残る＝ベストエフォート）。
    /// </remarks>
    public async Task<int> SaveAsync(
        TEntity entity,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entity);

        // フック登録があれば、進行中のストア書き込みに参加する context を供給するセッションを組み立てる
        var hooks =
            _saveHooks is null
                ? null
                : new SaveHookSession(
                    _saveHooks,
                    e => new InMemorySaveHookContext(Store, e.GetType())
                );

        // フェーズ 1（lock 外）: グラフを Save と同一順序で走査し Before を発火してスキップ集合を作る
        if (hooks is not null)
        {
            await InMemoryCascade.InvokeBeforeGraphAsync(
                entity,
                hooks,
                cascadeSave,
                cascadeDelete,
                cancellationToken
            );
        }

        // フェーズ 2（lock 内）: スキップ集合を適用して保存し、実行した (entity, 操作) を記録する
        var records =
            hooks is null ? null : new List<(EntityBase Entity, SaveOperation Operation)>();
        var rows = Store.Write(scope =>
            InMemoryCascade.Save(
                entity,
                scope,
                cascadeSave,
                cascadeDelete,
                insertWhenUpdateMissing,
                hooks,
                records
            )
        );

        // フェーズ 3（lock 外）: 実行順に After を発火する
        if (hooks is not null)
        {
            foreach (var (recordEntity, operation) in records!)
            {
                await hooks.InvokeAfterAsync(recordEntity, operation, cancellationToken);
            }
        }

        // 保存済みグラフを Unchanged 確定する（スキップされた行は据え置き）
        EntityGraphSaver.AcceptChanges(entity, cascadeSave, hooks?.Skipped);
        return rows;
    }

    /// <summary>複数の集約ルートを 1 まとめで保存する（全件成功か全件ロールバックの原子的処理）</summary>
    /// <remarks>フックの発火順序は単一版と同じく 3 フェーズ（Before プリパス → 保存 → After ポストパス）で、ルートは指定順に処理する。</remarks>
    public async Task<int> SaveAsync(
        IEnumerable<TEntity> entities,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);
        var roots = entities.Where(entity => entity is not null).ToList();

        var hooks =
            _saveHooks is null
                ? null
                : new SaveHookSession(
                    _saveHooks,
                    e => new InMemorySaveHookContext(Store, e.GetType())
                );

        // フェーズ 1（lock 外）: 全ルートのグラフを走査して Before を発火する
        if (hooks is not null)
        {
            foreach (var entity in roots)
            {
                await InMemoryCascade.InvokeBeforeGraphAsync(
                    entity,
                    hooks,
                    cascadeSave,
                    cascadeDelete,
                    cancellationToken
                );
            }
        }

        // フェーズ 2（lock 内）: スキップを適用して全ルートを保存し、実行した (entity, 操作) を記録する
        var records =
            hooks is null ? null : new List<(EntityBase Entity, SaveOperation Operation)>();
        var rows = Store.Write(scope =>
        {
            var total = 0;

            foreach (var entity in roots)
            {
                total += InMemoryCascade.Save(
                    entity,
                    scope,
                    cascadeSave,
                    cascadeDelete,
                    insertWhenUpdateMissing,
                    hooks,
                    records
                );
            }

            return total;
        });

        // フェーズ 3（lock 外）: 実行順に After を発火する
        if (hooks is not null)
        {
            foreach (var (recordEntity, operation) in records!)
            {
                await hooks.InvokeAfterAsync(recordEntity, operation, cancellationToken);
            }
        }

        foreach (var entity in roots)
        {
            EntityGraphSaver.AcceptChanges(entity, cascadeSave, hooks?.Skipped);
        }

        return rows;
    }

    /// <summary>生 SQL はインメモリでは実行できない</summary>
    public Task<IReadOnlyList<TEntity>> QueryBySqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => throw new NotSupportedException(RawSqlNotSupported);

    /// <summary>生 SQL はインメモリでは実行できない</summary>
    public Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => throw new NotSupportedException(RawSqlNotSupported);

    /// <summary>生 SQL はインメモリでは実行できない</summary>
    public Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => throw new NotSupportedException(RawSqlNotSupported);

    /// <summary>主キー引数（TKey）を辞書キーへ正規化する（値オブジェクトは内包値へ開く）</summary>
    private static object NormalizeKey(TKey id)
    {
        object? raw = id;

        return raw
            ?? throw new ArgumentNullException(nameof(id), "主キーに null は指定できません。");
    }
}

/// <summary>Save フックの After に渡す、進行中のストア書き込みに参加するインメモリコンテキスト（エンティティ型に束縛して生成する）</summary>
/// <remarks>
/// 除外列バイナリの書き込みは既存のインメモリ Stream アクセサと同じ Stream→byte[] 変換でストアへ反映する
/// （<c>ResolveWriteLength</c> の契約検証・クローン/Put 意味論を厳守）。生 SQL はインメモリでは実行できないため
/// <see cref="NotSupportedException"/> を投げる。インメモリは実トランザクションを持たないため、After が例外を投げても
/// ここで書き込んだストア変更は残る（ロールバックなし＝ベストエフォート）。
/// </remarks>
internal sealed class InMemorySaveHookContext(InMemoryDataStore store, Type entityType)
    : ISaveHookContext
{
    private readonly InMemoryDataStore _store = store;
    private readonly Type _entityType = entityType;

    /// <summary>インメモリでは生 SQL を実行できない（実 DB の Repository へ切り替えるか、フック外で処理する）</summary>
    public Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) =>
        throw new NotSupportedException(
            "インメモリ Repository は生 SQL を実行できません。実 DB の Repository へ切り替えてください。"
        );

    /// <summary>進行中のストア書き込みへ無制限バイナリ（除外）列をストリーム書き込みする（実 DB のストリーミングに対するパリティ）</summary>
    public async Task<bool> WriteBinaryColumnAsync(
        string propertyName,
        object key,
        Stream? source,
        long? length = null,
        CancellationToken cancellationToken = default
    )
    {
        var column = EntitySaveMetadata.For(_entityType).ColumnByPropertyName(propertyName);
        object? stored;

        if (source is null)
        {
            stored = null;
        }
        else
        {
            // CanSeek/length の契約検証は実 DB と揃える（方言中立パリティ）
            _ = UnboundedBinaryColumns.ResolveWriteLength(source, length);

            // インメモリは実 DB のストリーミングを持たないため全読みして byte[] 化する（契約・意味論は同一）
            using var buffer = new MemoryStream();
            await source.CopyToAsync(
                buffer,
                UnboundedBinaryColumns.StreamCopyBufferSize,
                cancellationToken
            );
            var bytes = buffer.ToArray();
            stored = bytes;
        }

        return _store.WriteColumnValue(_entityType, NormalizeKey(key), column, stored);
    }

    /// <summary>主キー（object）を辞書キーへ正規化する（値オブジェクトは内包値へ開く）</summary>
    private static object NormalizeKey(object key)
    {
        object? raw = key;

        return raw
            ?? throw new ArgumentNullException(nameof(key), "主キーに null は指定できません。");
    }
}

/// <summary>DocumentEntity 用リポジトリのインメモリ実装</summary>
public sealed partial class InMemoryDocumentRepository(
    InMemoryDataStore store,
    ISaveHookRegistry? saveHooks = null
)
    : InMemoryRepository<DocumentEntity, int>(
        store,
        saveHooks
    ),
        IDocumentRepository
{
    /// <summary>文書 ID と本体バイナリ（除外列 payload）を射影で取得する（文書 ID 昇順）</summary>
    public Task<IReadOnlyList<DocumentPayloadRow>> GetPayloadsAsync(CancellationToken cancellationToken = default) =>
        Query().OrderBy(e => e.DocumentId).ToProjectionListAsync(e => new DocumentPayloadRow { DocumentId = e.DocumentId, Payload = e.Payload }, cancellationToken);

    /// <summary>タイトル完全一致で文書を取得する（除外列 payload は取得されない）</summary>
    public Task<IReadOnlyList<DocumentEntity>> GetByTitleAsync(string title, CancellationToken cancellationToken = default) =>
        Query().Where(e => e.Title == title).ToListAsync(cancellationToken);

    /// <summary>本体バイナリ（payload）が存在する文書の件数を取得する</summary>
    public Task<int> CountWithPayloadAsync(CancellationToken cancellationToken = default) =>
        Query().Where(e => e.Payload != null).CountAsync(cancellationToken);

    /// <inheritdoc />
    public Task<bool> ReadPayloadAsync(int id, Stream destination, CancellationToken cancellationToken = default) =>
        ReadUnboundedBinaryColumnAsync(nameof(DocumentEntity.Payload), id, destination, cancellationToken);

    /// <inheritdoc />
    public Task<bool> WritePayloadAsync(int id, Stream? source, long? length = null, CancellationToken cancellationToken = default) =>
        WriteUnboundedBinaryColumnAsync(nameof(DocumentEntity.Payload), id, source, length, cancellationToken);

    /// <inheritdoc />
    public Task<bool> ReadThumbAsync(int id, Stream destination, CancellationToken cancellationToken = default) =>
        ReadUnboundedBinaryColumnAsync(nameof(DocumentEntity.Thumb), id, destination, cancellationToken);

    /// <inheritdoc />
    public Task<bool> WriteThumbAsync(int id, Stream? source, long? length = null, CancellationToken cancellationToken = default) =>
        WriteUnboundedBinaryColumnAsync(nameof(DocumentEntity.Thumb), id, source, length, cancellationToken);
}

/// <summary>DocumentNoteEntity 用リポジトリのインメモリ実装</summary>
public sealed partial class InMemoryDocumentNoteRepository(
    InMemoryDataStore store,
    ISaveHookRegistry? saveHooks = null
)
    : InMemoryRepository<DocumentNoteEntity, int>(
        store,
        saveHooks
    ),
        IDocumentNoteRepository { }

/// <summary>決定的なサンプルデータをインメモリストアへ投入するシーダー（FK 依存順に 3 件/エンティティ）</summary>
/// <remarks>
/// 値は列メタから決定的に生成する（int キー=1,2,3・string キー="{TABLE}-00n"・Guid=固定シードから決定的・
/// 文字列列="{列名} n"・数値/日付は型ベースの固定値・NULL 可列は 3 件中 1 件を null）。
/// FK 列は親キーの実在値を参照するため、親→子の順で投入する。
/// </remarks>
public static class InMemorySampleData
{
    /// <summary>1 エンティティあたりの投入件数</summary>
    public const int RowsPerEntity = 3;

    /// <summary>すべてのエンティティへサンプルデータを投入する（親→子の FK 依存順）</summary>
    public static void Seed(InMemoryDataStore store)
    {
        ArgumentNullException.ThrowIfNull(store);
        SeedDocumentEntity(store);
        SeedDocumentNoteEntity(store);

    }

    /// <summary>documents のサンプルデータを投入する</summary>
    private static void SeedDocumentEntity(InMemoryDataStore store)
    {
        for (var index = 1; index <= RowsPerEntity; index++)
        {
            var entity = new DocumentEntity
            {
                DocumentId = index,
                Title = ($"title {index}").Length > 50 ? ($"title {index}")[..50] : ($"title {index}"),
                Payload = index == 3 ? null : new byte[] { (byte)index, (byte)(index + 1), (byte)(index + 2) },
                Thumb = new byte[] { (byte)index, (byte)(index + 1), (byte)(index + 2) },
                Checksum = index == 3 ? null : new byte[] { (byte)index, (byte)(index + 1), (byte)(index + 2) },
                RowVer = index == 3 ? null : new byte[] { (byte)index, (byte)(index + 1), (byte)(index + 2) },
            };
            entity.MarkAdded();
            store.Put(entity);
            entity.MarkUnchanged();
        }
    }

    /// <summary>document_notes のサンプルデータを投入する</summary>
    private static void SeedDocumentNoteEntity(InMemoryDataStore store)
    {
        for (var index = 1; index <= RowsPerEntity; index++)
        {
            var entity = new DocumentNoteEntity
            {
                NoteId = index,
                DocumentId = index,
                Note = ($"note {index}").Length > 100 ? ($"note {index}")[..100] : ($"note {index}"),
            };
            entity.MarkAdded();
            store.Put(entity);
            entity.MarkUnchanged();
        }
    }
}

/// <summary>インメモリ Repository 群を DI コンテナへ登録する拡張</summary>
public static class GeneratedInMemoryRepositoryServiceCollectionExtensions
{
    /// <summary>インメモリデータストア（Singleton）と各インメモリ Repository（Scoped）を登録する</summary>
    /// <param name="services">登録先のサービスコレクション</param>
    /// <param name="seedSampleData">true（既定）で <see cref="InMemorySampleData"/> の決定的サンプルデータを投入済みで登録する</param>
    public static IServiceCollection AddGeneratedInMemoryRepositories(
        this IServiceCollection services,
        bool seedSampleData = true
    )
    {
        ArgumentNullException.ThrowIfNull(services);

        var store = new InMemoryDataStore();

        if (seedSampleData)
        {
            InMemorySampleData.Seed(store);
        }

        services.AddSingleton(store);

        // Save フックのレジストリを既定登録する（ISaveHook<T> の登録が無ければ完全 no-op）
        services.TryAddScoped<ISaveHookRegistry>(provider => new ServiceProviderSaveHookRegistry(
            provider
        ));
        services.AddScoped<IDocumentRepository, InMemoryDocumentRepository>();
        services.AddScoped<IDocumentRemoteRepository>(provider =>
            provider.GetRequiredService<IDocumentRepository>()
        );
        services.AddScoped<IDocumentNoteRepository, InMemoryDocumentNoteRepository>();
        services.AddScoped<IDocumentNoteRemoteRepository>(provider =>
            provider.GetRequiredService<IDocumentNoteRepository>()
        );

        return services;
    }
}

/// <summary>
/// 既存スキーマへ接続する EF Core の DbContext。
/// </summary>
/// <remarks>
/// スキーマ作成（Migrations / EnsureCreated）は範囲外で、既存 Entity を既存テーブルへマッピングして
/// 読み書きするための構成のみを持つ。列の DB 型（HasColumnType）は焼き込まず、DDL 生成に委ねる
/// </remarks>
public partial class QuickErDbContext : DbContext
{
    /// <summary>オプションを受け取り DbContext を初期化する</summary>
    public QuickErDbContext(DbContextOptions<QuickErDbContext> options)
        : base(options) { }

    /// <summary>DocumentEntity の DbSet</summary>
    public DbSet<DocumentEntity> Documents => Set<DocumentEntity>();

    /// <summary>DocumentNoteEntity の DbSet</summary>
    public DbSet<DocumentNoteEntity> DocumentNotes => Set<DocumentNoteEntity>();

    /// <summary>エンティティごとのテーブル・キー・列・リレーションを Fluent API で構成する</summary>
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<DocumentEntity>(entity =>
        {
            entity.ToTable("documents");
            entity.HasKey(e => e.DocumentId);
            entity.Ignore(e => e.RowState);
            entity.Ignore(e => e.IsAdded);
            entity.Ignore(e => e.IsUpdated);
            entity.Ignore(e => e.IsRemoved);
            entity.Ignore(e => e.HasChanges);
            entity.Property(e => e.DocumentId).HasColumnName("document_id").IsRequired();
            entity.Property(e => e.Title).HasColumnName("title").IsRequired().HasMaxLength(50);
            entity.Property(e => e.Payload).HasColumnName("payload");
            entity.Property(e => e.Thumb).HasColumnName("thumb").IsRequired();
            entity.Property(e => e.Checksum).HasColumnName("checksum");
            entity.Property(e => e.RowVer).HasColumnName("row_ver").IsRowVersion();
            entity
                .HasMany(e => e.DocumentNotes)
                .WithOne(e => e.Document)
                .HasForeignKey(e => e.DocumentId)
                .OnDelete(DeleteBehavior.Cascade);
        });

        modelBuilder.Entity<DocumentNoteEntity>(entity =>
        {
            entity.ToTable("document_notes");
            entity.HasKey(e => e.NoteId);
            entity.Ignore(e => e.RowState);
            entity.Ignore(e => e.IsAdded);
            entity.Ignore(e => e.IsUpdated);
            entity.Ignore(e => e.IsRemoved);
            entity.Ignore(e => e.HasChanges);
            entity.Property(e => e.NoteId).HasColumnName("note_id").IsRequired();
            entity.Property(e => e.DocumentId).HasColumnName("document_id").IsRequired();
            entity.Property(e => e.Note).HasColumnName("note").IsRequired().HasMaxLength(100);
        });

        OnModelCreatingPartial(modelBuilder);
    }

    /// <summary>利用者が追加構成を差し込むための拡張ポイント（partial・未実装ならゼロコスト）</summary>
    partial void OnModelCreatingPartial(ModelBuilder modelBuilder);
}

/// <summary>エンティティに縛られない生 SQL 実行器の EF Core 版（DbContext の接続上で ADO を直接実行する）</summary>
/// <remarks>
/// <para>
/// EF Core の FromSqlRaw / SqlQueryRaw はマッピング規則が既存 SQL Server 版（厳密全列必須・寛容射影・単一値モード）と
/// 一致しないため、<typeparamref name="TContext"/> の <see cref="DbConnection"/> 上で <see cref="DbCommand"/> を
/// 直接実行し、既存版とマッピング・束縛の実装を共有する（意味論は <see cref="ISqlExecutor"/> の定義どおり）。
/// </para>
/// <para>
/// 具象 DbContext には依存せず <typeparamref name="TContext"/>（<see cref="DbContext"/> 派生）で受け取る。
/// 具象型は生成側（DI 登録・エンティティ別実装）で閉じる。
/// </para>
/// <para>ステートレス（コンテキストファクトリのみ保持）のため DI では Singleton 登録できる。</para>
/// </remarks>
/// <typeparam name="TContext">接続を提供する DbContext の具象型</typeparam>
public sealed partial class EfCoreSqlExecutor<TContext>(IDbContextFactory<TContext> contextFactory)
    : ISqlExecutor
    where TContext : DbContext
{
    /// <summary>DbContext の生成元</summary>
    private readonly IDbContextFactory<TContext> _contextFactory = contextFactory;

    /// <summary>生 SQL の SELECT を実行し、結果行を {TEntity} へ厳密（全列必須）にマップして返す</summary>
    public async Task<IReadOnlyList<TEntity>> QueryBySqlAsync<TEntity>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
        where TEntity : EntityBase, new()
    {
        ArgumentNullException.ThrowIfNull(sql);

        var metadata = EntitySaveMetadata.For(typeof(TEntity));
        var items = new List<TEntity>();

        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);
        await using var command = await CreateCommandAsync(
            context,
            sql,
            parameters,
            cancellationToken
        );
        await using var reader = await command.ExecuteReaderAsync(cancellationToken);

        while (await reader.ReadAsync(cancellationToken))
        {
            items.Add(metadata.MapEntityFromRawSql<TEntity>(reader));
        }

        return items;
    }

    /// <summary>生 SQL の SELECT を実行し、結果行を任意の <typeparamref name="TResult"/> へ寛容に射影して返す</summary>
    public async Task<IReadOnlyList<TResult>> QueryProjectionBySqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);
        await using var command = await CreateCommandAsync(
            context,
            sql,
            parameters,
            cancellationToken
        );
        await using var reader = await command.ExecuteReaderAsync(cancellationToken);

        // 射影マッピング（単一値モード・DTO モード）は共有ヘルパーの 1 系統を使う
        return await RawSqlMapper.ReadProjectionRowsAsync<TResult>(reader, cancellationToken);
    }

    /// <summary>生 SQL（UPDATE/DELETE/任意 DML）を実行し、影響行数を返す</summary>
    /// <remarks>
    /// 呼び出しごとに DbContext（接続）を開閉する（トランザクション引数なし）。複数文をアトミックに
    /// 実行したい場合は、1 回の呼び出し内に方言のトランザクション文（BEGIN ... COMMIT 等）を記述すること。
    /// </remarks>
    public async Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);
        await using var command = await CreateCommandAsync(
            context,
            sql,
            parameters,
            cancellationToken
        );

        return await command.ExecuteNonQueryAsync(cancellationToken);
    }

    /// <summary>生 SQL を実行し、単一のスカラー値を返す（該当なし・DBNull は <c>default</c>）</summary>
    public async Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);
        await using var command = await CreateCommandAsync(
            context,
            sql,
            parameters,
            cancellationToken
        );

        var scalar = await command.ExecuteScalarAsync(cancellationToken);
        return RawSqlMapper.ConvertSingleValue<TResult>(scalar is DBNull ? null : scalar);
    }

    /// <summary>接続を開き、SQL とパラメータを束縛した DbCommand を生成する（束縛規約は SQL Server 版と同一）</summary>
    private static async Task<DbCommand> CreateCommandAsync(
        TContext context,
        string sql,
        object? parameters,
        CancellationToken cancellationToken
    )
    {
        // 接続は DbContext が所有しており、DbContext の破棄で閉じられる
        await context.Database.OpenConnectionAsync(cancellationToken);

        var command = context.Database.GetDbConnection().CreateCommand();
        command.CommandText = sql;
        RawSqlMapper.BindParameters(command, parameters);
        return command;
    }
}

/// <summary>
/// <see cref="SqlQuery{TEntity}"/> の EF Core 実行器。捕捉された式木を LINQ クエリへ合成し、
/// 短命の <typeparamref name="TContext"/>（AsNoTracking）で実行する。
/// </summary>
/// <remarks>
/// Where は捕捉済みの述語式をそのまま適用し、各方言への翻訳は EF Core プロバイダに委ねる。
/// OrderBy は object? への boxing（Convert）を剥がして実キー型の OrderBy / ThenBy を合成する。
/// Include は <see cref="IncludeNode"/> ツリーから "Orders.Details" 形式のドットパスを組み立てて適用する。
/// 取得結果のグラフは既存 SQL Server 版のマッピングと同じく RowState=Unchanged に揃える。
/// 具象 DbContext には依存せず <typeparamref name="TContext"/>（<see cref="DbContext"/> 派生）で受け取る。
/// </remarks>
/// <typeparam name="TEntity">クエリ対象のエンティティ型</typeparam>
/// <typeparam name="TContext">クエリを実行する DbContext の具象型</typeparam>
internal sealed class EfCoreSqlQueryExecutor<TEntity, TContext>(
    IDbContextFactory<TContext> contextFactory
) : ISqlQueryExecutor<TEntity>
    where TEntity : EntityBase
    where TContext : DbContext
{
    /// <summary>DbContext の生成元</summary>
    private readonly IDbContextFactory<TContext> _contextFactory = contextFactory;

    /// <summary>条件に一致するエンティティを（Include 指定分とともに）一覧取得する</summary>
    public async Task<IReadOnlyList<TEntity>> ToListAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);

        var query = ApplyOrderings(
            ApplyIncludes(ApplyPredicates(context.Set<TEntity>().AsNoTracking(), plan), plan),
            plan
        );
        var items = await ApplyPaging(query, plan).ToListAsync(cancellationToken);

        foreach (var item in items)
        {
            MarkGraphUnchanged(item, plan.Includes);
        }

        return items;
    }

    /// <summary>条件に一致するエンティティを射影して取得する（列参照のみ・Include なしのときは EF Core にサーバー側射影させる）</summary>
    /// <remarks>
    /// Include があるか、セレクタから列参照のみを安全に抽出できない場合は、従来経路
    /// （全列取得 → メモリ内で射影）へフォールバックする。刈り込み可能時は、フィルタ・並び順・ページングを
    /// 適用した <see cref="IQueryable{T}"/> に <c>Select(selector)</c> を直適用し、EF Core に列を絞らせる。
    /// </remarks>
    public async Task<IReadOnlyList<TResult>> ToProjectionListAsync<TResult>(
        SqlQueryPlan<TEntity> plan,
        Expression<Func<TEntity, TResult>> selector,
        CancellationToken cancellationToken
    )
    {
        // Include なし・列参照のみのときだけ EF Core の Select 直適用でサーバー側射影する（可否判定は ADO と同じ収集器）
        var prunable =
            plan.Includes.Count == 0
            && ProjectionColumnCollector.TryCollect(selector, out var referenced)
            && EntitySaveMetadata.For(typeof(TEntity)).ResolveProjectionColumns(referenced) is not null;

        if (!prunable)
        {
            // フォールバック: 全列（Include 分含む）を取得してからメモリ内で射影する
            var entities = await ToListAsync(plan, cancellationToken);
            return entities.Select(selector.Compile()).ToList();
        }

        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);

        // Include は無い前提のため適用しない。並び順・ページングを適用してから Select を直適用する
        var query = ApplyPaging(
            ApplyOrderings(ApplyPredicates(context.Set<TEntity>().AsNoTracking(), plan), plan),
            plan
        );

        return await query.Select(selector).ToListAsync(cancellationToken);
    }

    /// <summary>条件に一致する先頭の 1 件を（Include 指定分とともに）取得する（該当なしは null）</summary>
    public async Task<TEntity?> FirstOrDefaultAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);

        var query = ApplyOrderings(
            ApplyIncludes(ApplyPredicates(context.Set<TEntity>().AsNoTracking(), plan), plan),
            plan
        );

        // 既存版と同じく Take は 1 に固定し、Skip のみ尊重する
        if (plan.Skip is int skip)
        {
            query = query.Skip(skip);
        }

        var item = await query.FirstOrDefaultAsync(cancellationToken);

        if (item is not null)
        {
            MarkGraphUnchanged(item, plan.Includes);
        }

        return item;
    }

    /// <summary>条件に一致する件数を取得する（既存版と同じく並び順・ページング・Include は関与しない）</summary>
    public async Task<int> CountAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);

        return await ApplyPredicates(context.Set<TEntity>().AsNoTracking(), plan)
            .CountAsync(cancellationToken);
    }

    /// <summary>条件に一致するレコードが存在するかを取得する（既存版と同じく並び順・ページング・Include は関与しない）</summary>
    public async Task<bool> AnyAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);

        return await ApplyPredicates(context.Set<TEntity>().AsNoTracking(), plan)
            .AnyAsync(cancellationToken);
    }

    /// <summary>条件に一致する行を一括削除する。cascadeDelete=true で子孫も FK 連鎖で削除する</summary>
    public async Task<int> ExecuteDeleteAsync(
        SqlQueryPlan<TEntity> plan,
        bool cascadeDelete,
        CancellationToken cancellationToken
    )
    {
        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);
        var roots = ApplyPredicates(context.Set<TEntity>(), plan);

        if (!cascadeDelete)
        {
            return await roots.ExecuteDeleteAsync(cancellationToken);
        }

        // カスケード: 子孫 → 本体の順の ExecuteDelete を 1 トランザクションで実行する（既存版の DELETE 文順序と同じ）
        await using var transaction = await context.Database.BeginTransactionAsync(
            cancellationToken
        );
        var rows = await DeleteSubtreeAsync(
            context,
            roots,
            new HashSet<Type> { typeof(TEntity) },
            cancellationToken
        );
        await transaction.CommitAsync(cancellationToken);
        return rows;
    }

    /// <summary>DeleteSubtreeAsync を実行時の子型でジェネリック展開するためのメソッド情報</summary>
    private static readonly MethodInfo _deleteSubtreeMethod = typeof(
        EfCoreSqlQueryExecutor<TEntity, TContext>
    ).GetMethod(nameof(DeleteSubtreeAsync), BindingFlags.NonPublic | BindingFlags.Static)!;

    /// <summary>クエリに一致する行の子孫を末端（孫）から順に削除し、最後に自身を削除する（削除行数を返す）</summary>
    private static async Task<int> DeleteSubtreeAsync<TCurrent>(
        TContext context,
        IQueryable<TCurrent> query,
        ISet<Type> visited,
        CancellationToken cancellationToken
    )
        where TCurrent : class
    {
        var rows = 0;

        foreach (var navigation in EntitySaveMetadata.For(typeof(TCurrent)).CascadeNavigations)
        {
            if (!visited.Add(navigation.ChildType))
            {
                throw new NotSupportedException(
                    $"循環するカスケード（{navigation.ChildType.Name}）は ExecuteDeleteAsync では未対応です。グラフをロードして SaveAsync を使うか、DB の ON DELETE CASCADE を利用してください。"
                );
            }

            // 子クエリ: child => 親クエリの主キー集合.Contains(child.FK)（EF Core が IN サブクエリへ翻訳する）
            var childQuery = BuildChildQuery(context, query, typeof(TCurrent), navigation);
            var subtreeTask = (Task<int>)
                _deleteSubtreeMethod
                    .MakeGenericMethod(navigation.ChildType)
                    .Invoke(null, new object[] { context, childQuery, visited, cancellationToken })!;
            rows += await subtreeTask;

            visited.Remove(navigation.ChildType);
        }

        rows += await query.ExecuteDeleteAsync(cancellationToken);
        return rows;
    }

    /// <summary>DbContext.Set&lt;T&gt;() を実行時型で呼び出すためのメソッド情報</summary>
    private static readonly MethodInfo _setMethod = typeof(DbContext).GetMethod(
        nameof(DbContext.Set),
        Type.EmptyTypes
    )!;

    /// <summary>親クエリの主キー集合を参照する子クエリ（child => parentKeys.Contains(child.FK)）を組み立てる</summary>
    private static IQueryable BuildChildQuery(
        TContext context,
        IQueryable parentQuery,
        Type parentType,
        CascadeNavigation navigation
    )
    {
        var parentKeyProperty = EntitySaveMetadata
            .For(parentType)
            .PropertyByColumn[navigation.PrincipalColumn];
        var childForeignKeyProperty = EntitySaveMetadata
            .For(navigation.ChildType)
            .PropertyByColumn[navigation.DependentColumn];

        // parentKeys = parentQuery.Select(parent => parent.Key)
        var parentParameter = Expression.Parameter(parentType, "parent");
        var keySelector = Expression.Lambda(
            Expression.Property(parentParameter, parentKeyProperty),
            parentParameter
        );
        var parentKeys = parentQuery.Provider.CreateQuery(
            Expression.Call(
                typeof(Queryable),
                nameof(Queryable.Select),
                new[] { parentType, parentKeyProperty.PropertyType },
                parentQuery.Expression,
                Expression.Quote(keySelector)
            )
        );

        // childSet.Where(child => parentKeys.Contains(child.FK))。FK が Nullable の場合はキー型へ変換して比較する
        var childParameter = Expression.Parameter(navigation.ChildType, "child");
        var foreignKeyAccess = (Expression)
            Expression.Property(childParameter, childForeignKeyProperty);

        if (foreignKeyAccess.Type != parentKeyProperty.PropertyType)
        {
            foreignKeyAccess = Expression.Convert(foreignKeyAccess, parentKeyProperty.PropertyType);
        }

        var predicate = Expression.Lambda(
            Expression.Call(
                typeof(Queryable),
                nameof(Queryable.Contains),
                new[] { parentKeyProperty.PropertyType },
                Expression.Constant(
                    parentKeys,
                    typeof(IQueryable<>).MakeGenericType(parentKeyProperty.PropertyType)
                ),
                foreignKeyAccess
            ),
            childParameter
        );
        var childSet = (IQueryable)
            _setMethod.MakeGenericMethod(navigation.ChildType).Invoke(context, null)!;

        return childSet.Provider.CreateQuery(
            Expression.Call(
                typeof(Queryable),
                nameof(Queryable.Where),
                new[] { navigation.ChildType },
                childSet.Expression,
                Expression.Quote(predicate)
            )
        );
    }

    /// <summary>捕捉済みの Where 式を適用する（AND 結合）</summary>
    private static IQueryable<TEntity> ApplyPredicates(
        IQueryable<TEntity> query,
        SqlQueryPlan<TEntity> plan
    )
    {
        foreach (var predicate in plan.Predicates)
        {
            query = query.Where((Expression<Func<TEntity, bool>>)predicate);
        }

        return query;
    }

    /// <summary>捕捉済みの並び順を適用する（boxing を剥がし実キー型で OrderBy / ThenBy を合成する）</summary>
    private static IQueryable<TEntity> ApplyOrderings(
        IQueryable<TEntity> query,
        SqlQueryPlan<TEntity> plan
    )
    {
        var first = true;

        foreach (var ordering in plan.Orderings)
        {
            var body = ordering.KeySelector.Body;

            while (
                body is UnaryExpression
                {
                    NodeType: ExpressionType.Convert or ExpressionType.ConvertChecked
                } unary
            )
            {
                body = unary.Operand;
            }

            var keyLambda = Expression.Lambda(body, ordering.KeySelector.Parameters);
            var methodName = (first, ordering.Descending) switch
            {
                (true, false) => nameof(Queryable.OrderBy),
                (true, true) => nameof(Queryable.OrderByDescending),
                (false, false) => nameof(Queryable.ThenBy),
                (false, true) => nameof(Queryable.ThenByDescending),
            };
            query = query.Provider.CreateQuery<TEntity>(
                Expression.Call(
                    typeof(Queryable),
                    methodName,
                    new[] { typeof(TEntity), body.Type },
                    query.Expression,
                    Expression.Quote(keyLambda)
                )
            );
            first = false;
        }

        return query;
    }

    /// <summary>Include ツリーからドットパス（例: "Orders.Details"）を組み立てて適用する</summary>
    private static IQueryable<TEntity> ApplyIncludes(
        IQueryable<TEntity> query,
        SqlQueryPlan<TEntity> plan
    )
    {
        foreach (var node in plan.Includes)
        {
            foreach (var path in EnumerateIncludePaths(node, node.Property.Name))
            {
                query = query.Include(path);
            }
        }

        return query;
    }

    /// <summary>Include ノードからルート→末端のドットパスを列挙する（子が無いノードはそのパス自身）</summary>
    private static IEnumerable<string> EnumerateIncludePaths(IncludeNode node, string path)
    {
        if (node.Children.Count == 0)
        {
            yield return path;
            yield break;
        }

        foreach (var child in node.Children)
        {
            foreach (var childPath in EnumerateIncludePaths(child, $"{path}.{child.Property.Name}"))
            {
                yield return childPath;
            }
        }
    }

    /// <summary>Skip / Take を適用する（既存版の OFFSET / FETCH と同じ意味）</summary>
    private static IQueryable<TEntity> ApplyPaging(
        IQueryable<TEntity> query,
        SqlQueryPlan<TEntity> plan
    )
    {
        if (plan.Skip is int skip)
        {
            query = query.Skip(skip);
        }

        if (plan.Take is int take)
        {
            query = query.Take(take);
        }

        return query;
    }

    /// <summary>取得したグラフ（ルート＋Include で読んだ範囲）を RowState=Unchanged に揃える（既存版のマッピング後状態と同じ）</summary>
    private static void MarkGraphUnchanged(EntityBase entity, IReadOnlyList<IncludeNode> includes)
    {
        entity.MarkUnchanged();

        foreach (var node in includes)
        {
            var value = node.Property.GetValue(entity);

            if (value is null)
            {
                continue;
            }

            if (value is IEnumerable<EntityBase> children)
            {
                foreach (var child in children)
                {
                    if (child is not null)
                    {
                        MarkGraphUnchanged(child, node.Children);
                    }
                }
            }
            else if (value is EntityBase child)
            {
                MarkGraphUnchanged(child, node.Children);
            }
        }
    }
}

/// <summary>メタデータと EF Core（<typeparamref name="TContext"/>）で CRUD を実装するリポジトリ基底クラス</summary>
/// <remarks>
/// <para>
/// QuickER の SQL Server 実装（<see cref="SqliteRepository{TEntity, TKey}"/>）と同じ契約を DbContext ベースで
/// 実装する。DbContext は呼び出し単位で短命に生成し（呼び出しごとに接続を開く単位と同じ）、
/// 読み取りは AsNoTracking、保存は <c>ChangeTracker.TrackGraph</c> による RowState → EntityState 変換で行う。
/// </para>
/// <para>
/// 具象 DbContext には依存せず <typeparamref name="TContext"/>（<see cref="DbContext"/> 派生）で受け取る。
/// 具象型（QuickErDbContext 等）は生成側（エンティティ別実装・DI 登録）で閉じる。
/// </para>
/// <para>UseSqlServer / UseNpgsql 等の方言選択はアプリ側の DbContextOptions 構成に委ねる（方言非依存）。</para>
/// </remarks>
/// <typeparam name="TEntity">対象エンティティ型</typeparam>
/// <typeparam name="TKey">主キー型</typeparam>
/// <typeparam name="TContext">CRUD を実行する DbContext の具象型</typeparam>
public abstract partial class EfCoreRepository<TEntity, TKey, TContext>(
    IDbContextFactory<TContext> contextFactory,
    ISaveHookRegistry? saveHooks = null
) : IRepository<TEntity, TKey>
    where TEntity : EntityBase, new()
    where TContext : DbContext
{
    /// <summary>エンティティ型ごとに 1 度だけ構築されるメタデータ（静的フィールドで再利用）</summary>
    private static readonly EntitySaveMetadata _metadata = EntitySaveMetadata.For(typeof(TEntity));

    /// <summary>DbContext の生成元</summary>
    private readonly IDbContextFactory<TContext> _contextFactory = contextFactory;

    /// <summary>生 SQL メソッドの委譲先（束縛・マッピングを 1 系統に集約）</summary>
    private readonly ISqlExecutor _sqlExecutor = new EfCoreSqlExecutor<TContext>(contextFactory);

    /// <summary>Save フックのレジストリ（未指定＝null＝フックなしで完全 no-op）</summary>
    private readonly ISaveHookRegistry? _saveHooks = saveHooks;

    /// <summary>TrackGraph で記録した「保存対象エンティティ・EF Core エントリ・実行操作」の 1 件（操作は再試行での切替で更新される）</summary>
    private sealed class TrackedOperation(
        EntityBase entity,
        EntityEntry entry,
        SaveOperation operation
    )
    {
        /// <summary>保存対象エンティティ</summary>
        public EntityBase Entity { get; } = entity;

        /// <summary>対応する EF Core の追跡エントリ（State の落とし込み・再試行での型判定に使う）</summary>
        public EntityEntry Entry { get; } = entry;

        /// <summary>実際に行う操作（<c>insertWhenUpdateMissing</c> の切替時に Update→Insert へ更新される）</summary>
        public SaveOperation Operation { get; set; } = operation;
    }

    /// <summary>主キーによる単一エンティティ取得（該当なしは null）</summary>
    /// <remarks>既存版と同じく単一テーブルのみを読む（ナビゲーションのロードは <see cref="Query"/> の Include で行う）</remarks>
    public async Task<TEntity?> GetByIdAsync(TKey id, CancellationToken cancellationToken = default)
    {
        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);

        var entity = await context
            .Set<TEntity>()
            .AsNoTracking()
            .FirstOrDefaultAsync(BuildKeyPredicate(id), cancellationToken);
        // DB から読み込んだ行は変更なし扱いにする（既存版 MapEntity と同じ事後状態）
        entity?.MarkUnchanged();
        return entity;
    }

    /// <summary>全エンティティ取得</summary>
    public async Task<IReadOnlyList<TEntity>> GetAllAsync(
        CancellationToken cancellationToken = default
    )
    {
        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);

        var items = await context.Set<TEntity>().AsNoTracking().ToListAsync(cancellationToken);

        foreach (var item in items)
        {
            item.MarkUnchanged();
        }

        return items;
    }

    /// <summary>エンティティ追加</summary>
    public async Task InsertAsync(TEntity entity, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(entity);

        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);

        // Add はナビゲーション先まで Added にするため、Entry.State 代入で対象 1 件のみを追加する（既存版の単発 INSERT と同じ範囲）
        context.Entry(entity).State = EntityState.Added;
        await context.SaveChangesAsync(cancellationToken);
    }

    /// <summary>エンティティのコレクションを一括追加する</summary>
    /// <remarks>
    /// EF Core 版は全件を Added で追跡して 1 回の SaveChanges で保存する（バッチ化された INSERT 文）。
    /// SqlBulkCopy を使う既存 SQL Server 版とは性能特性が異なり、大量件数では遅くなる可能性がある。
    /// 挿入範囲は既存版と同じく渡されたエンティティのみで、ナビゲーション先はたどらない。
    /// </remarks>
    public async Task<int> BulkInsertAsync(
        IEnumerable<TEntity> entities,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);

        // 件数が確定しているコレクションが空なら DbContext を作らずに終了する
        if (entities is ICollection<TEntity> { Count: 0 })
        {
            return 0;
        }

        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);

        foreach (var entity in entities)
        {
            // AddRange はナビゲーション先まで Added にするため、Entry.State 代入で対象のみを追加する
            context.Entry(entity).State = EntityState.Added;
        }

        return await context.SaveChangesAsync(cancellationToken);
    }

    /// <summary>エンティティ更新（更新対象ありで true）</summary>
    public async Task<bool> UpdateAsync(
        TEntity entity,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entity);

        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);
        context.Entry(entity).State = EntityState.Modified;

        try
        {
            await context.SaveChangesAsync(cancellationToken);
            return true;
        }
        catch (DbUpdateConcurrencyException)
        {
            // 更新対象が存在しない（既存版の「影響 0 行 → false」と同じ契約）
            return false;
        }
    }

    /// <summary>主キーによるエンティティ削除（削除対象ありで true）</summary>
    public async Task<bool> DeleteAsync(TKey id, CancellationToken cancellationToken = default)
    {
        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);

        var affected = await context
            .Set<TEntity>()
            .Where(BuildKeyPredicate(id))
            .ExecuteDeleteAsync(cancellationToken);
        return affected > 0;
    }

    /// <summary>検索条件・並び順・Include をチェーン指定して取得するクエリを開始する（EF Core で実行）</summary>
    public SqlQuery<TEntity> Query() =>
        new(new EfCoreSqlQueryExecutor<TEntity, TContext>(_contextFactory));

    /// <summary>RowState に従って 1 トランザクションで追加・更新・削除を保存する（既定で子をカスケード）</summary>
    public async Task<int> SaveAsync(
        TEntity entity,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entity);

        // グラフ全体に変更が無ければ DbContext も作らずに終了する
        if (!EntityGraphSaver.HasChanges(entity, cascadeSave))
        {
            return 0;
        }

        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);

        var tracked = new List<TrackedOperation>();
        TrackGraph(context, entity, cascadeSave, cascadeDelete, tracked);

        return await SaveTrackedGraphAsync(
            context,
            [entity],
            tracked,
            cascadeSave,
            insertWhenUpdateMissing,
            cancellationToken
        );
    }

    /// <summary>複数の集約ルートを 1 トランザクションでまとめて保存する（全件成功か全件ロールバックの原子的処理）</summary>
    public async Task<int> SaveAsync(
        IEnumerable<TEntity> entities,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);

        // 変更のあるグラフだけを対象にする（DbContext を作る前に絞り込む）
        var targets = entities
            .Where(entity => entity is not null && EntityGraphSaver.HasChanges(entity, cascadeSave))
            .ToList();

        if (targets.Count == 0)
        {
            return 0;
        }

        await using var context = await _contextFactory.CreateDbContextAsync(cancellationToken);

        var tracked = new List<TrackedOperation>();

        foreach (var entity in targets)
        {
            TrackGraph(context, entity, cascadeSave, cascadeDelete, tracked);
        }

        return await SaveTrackedGraphAsync(
            context,
            targets,
            tracked,
            cascadeSave,
            insertWhenUpdateMissing,
            cancellationToken
        );
    }

    /// <summary>
    /// 追跡済みグラフを保存する。記録された型のどれかに Save フックの登録があるときだけフック経路（明示トランザクション内で
    /// Before → SaveChanges → After → Commit）に入り、1 つも無ければ<b>完全に既存経路</b>（明示トランザクションを張らず
    /// SaveChanges を 1 回実行する＝意味的に従来と同一）で処理する。
    /// </summary>
    private async Task<int> SaveTrackedGraphAsync(
        TContext context,
        IReadOnlyList<TEntity> roots,
        List<TrackedOperation> tracked,
        bool cascadeSave,
        bool insertWhenUpdateMissing,
        CancellationToken cancellationToken
    )
    {
        // 記録された型のどれかにフック登録があるときだけフック経路に入る（1 つも無ければ既存経路）
        var hasHooks =
            _saveHooks is not null
            && tracked.Any(op => _saveHooks.GetInvoker(op.Entity.GetType()) is not null);

        if (!hasHooks)
        {
            // 既存経路: 明示トランザクションなしで SaveChanges（内部で 1 トランザクションとして実行される）
            var rowsWithoutHooks = await SaveTrackedChangesAsync(
                context,
                tracked,
                insertWhenUpdateMissing,
                cancellationToken
            );

            foreach (var root in roots)
            {
                EntityGraphSaver.AcceptChanges(root, cascadeSave);
            }

            return rowsWithoutHooks;
        }

        // フック経路: After に保存中 context（＋その CurrentTransaction）を閉じ込めた context を供給するセッション
        var hooks = new SaveHookSession(_saveHooks!, _ => new EfCoreSaveHookContext(context));

        // Before パス（SaveChanges 前）: 記録順に発火し、false は Entry を Unchanged に落として保存対象から除く
        var survivors = new List<TrackedOperation>(tracked.Count);

        foreach (var op in tracked)
        {
            if (await hooks.InvokeBeforeAsync(op.Entity, op.Operation, cancellationToken))
            {
                survivors.Add(op);
            }
            else
            {
                op.Entry.State = EntityState.Unchanged;
                hooks.Skip(op.Entity);
            }
        }

        // After を「操作後・コミット前」に発火するため、SaveChanges を明示トランザクション内で行う
        await using var transaction = await context.Database.BeginTransactionAsync(cancellationToken);

        var rows = await SaveTrackedChangesAsync(
            context,
            survivors,
            insertWhenUpdateMissing,
            cancellationToken
        );

        // After パス（コミット前）: 記録順に、実際に行った操作（切替時は Insert）で発火する
        foreach (var op in survivors)
        {
            await hooks.InvokeAfterAsync(op.Entity, op.Operation, cancellationToken);
        }

        await transaction.CommitAsync(cancellationToken);

        // 保存成功後に状態を確定（Added/Updated → Unchanged）し、スキップされた行は据え置く
        foreach (var root in roots)
        {
            EntityGraphSaver.AcceptChanges(root, cascadeSave, hooks.Skipped);
        }

        return rows;
    }

    /// <summary>生 SQL の SELECT を実行し、結果行を {TEntity} へマップして返す</summary>
    /// <remarks>
    /// マッピング・束縛の意味論は既存 SQL Server 版と同一（全列必須・RowState=Unchanged）。
    /// 実装は <see cref="ISqlExecutor"/>（EF Core 版）へ委譲する（束縛・マッピングの 1 系統化）。
    /// </remarks>
    public Task<IReadOnlyList<TEntity>> QueryBySqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.QueryBySqlAsync<TEntity>(sql, parameters, cancellationToken);

    /// <summary>生 SQL（UPDATE/DELETE/任意 DML）を実行し、影響行数を返す</summary>
    /// <remarks>
    /// 呼び出しごとに DbContext（接続）を開閉する。複数文をアトミックに実行したい場合は、
    /// 1 回の呼び出し内に方言のトランザクション文を記述すること。実装は <see cref="ISqlExecutor"/>（EF Core 版）へ委譲する。
    /// </remarks>
    public Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.ExecuteSqlAsync(sql, parameters, cancellationToken);

    /// <summary>生 SQL を実行し、単一のスカラー値を返す（該当なし・DBNull は <c>default</c>）</summary>
    /// <remarks>変換・束縛の意味論は既存 SQL Server 版と同一。実装は <see cref="ISqlExecutor"/>（EF Core 版）へ委譲する。</remarks>
    public Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.ExecuteScalarSqlAsync<TResult>(sql, parameters, cancellationToken);

    /// <summary>主キー等値の述語式（e => e.Key == id）をメタデータから組み立てる</summary>
    private static Expression<Func<TEntity, bool>> BuildKeyPredicate(TKey id)
    {
        var parameter = Expression.Parameter(typeof(TEntity), "e");
        var body = Expression.Equal(
            Expression.Property(parameter, _metadata.KeyProperty),
            Expression.Constant(id, _metadata.KeyProperty.PropertyType)
        );
        return Expression.Lambda<Func<TEntity, bool>>(body, parameter);
    }

    /// <summary>RowState → EntityState の変換でグラフを DbContext へ登録し、保存対象（非 Unchanged）を <paramref name="tracked"/> へ記録する（切断パターンの保存前処理）</summary>
    /// <remarks>記録順はグラフの走査順（ルート→子）で、Save フックの Before/After はこの順で発火する。Deleted サブツリーの子も削除グループとして記録する。</remarks>
    private static void TrackGraph(
        TContext context,
        TEntity entity,
        bool cascadeSave,
        bool cascadeDelete,
        List<TrackedOperation> tracked
    )
    {
        if (!cascadeSave)
        {
            // 子をたどらず、ルート 1 件のみを保存対象にする
            var entry = context.Entry(entity);
            entry.State = ToEntityState(entity.RowState);
            RecordOperation(tracked, entity, entry);
            return;
        }

        context.ChangeTracker.TrackGraph(
            entity,
            node =>
            {
                var current = (EntityBase)node.Entry.Entity;

                // 親が削除対象なら配下の扱いは cascadeDelete に従う（既存版の子孫先行 DELETE と同じ）
                if (node.SourceEntry is { State: EntityState.Deleted })
                {
                    // cascadeDelete=false なら配下は対象外（Detached のままにすると配下の走査も止まる）。
                    // Added（DB 未挿入）の子は削除対象が存在しないため対象外（既存版の DELETE 影響 0 行と同じ結果）
                    if (cascadeDelete && !current.IsAdded)
                    {
                        node.Entry.State = EntityState.Deleted;
                        RecordOperation(tracked, current, node.Entry);
                    }

                    return;
                }

                // Unchanged も追跡させ（EntityState.Unchanged）、配下の変更ノードまで走査を継続する
                node.Entry.State = ToEntityState(current.RowState);
                RecordOperation(tracked, current, node.Entry);
            }
        );
    }

    /// <summary>EntityState が保存対象（Added/Modified/Deleted）ならフック発火用の記録を追加する（Unchanged は無視）</summary>
    private static void RecordOperation(
        List<TrackedOperation> tracked,
        EntityBase entity,
        EntityEntry entry
    )
    {
        var operation = entry.State switch
        {
            EntityState.Added => (SaveOperation?)SaveOperation.Insert,
            EntityState.Modified => SaveOperation.Update,
            EntityState.Deleted => SaveOperation.Delete,
            _ => null,
        };

        if (operation is { } value)
        {
            tracked.Add(new TrackedOperation(entity, entry, value));
        }
    }

    /// <summary>RowState を EF Core の EntityState へ変換する</summary>
    private static EntityState ToEntityState(RowState rowState) =>
        rowState switch
        {
            RowState.Added => EntityState.Added,
            RowState.Updated => EntityState.Modified,
            RowState.Removed => EntityState.Deleted,
            _ => EntityState.Unchanged,
        };

    /// <summary>
    /// SaveChanges を実行し、<see cref="DbUpdateConcurrencyException"/> を既存契約へ変換する
    /// （insertWhenUpdateMissing=true なら更新対象なしの UPDATE を INSERT へ切り替えて再試行、
    /// それ以外は <see cref="SaveConflictException"/>）。
    /// </summary>
    private static async Task<int> SaveTrackedChangesAsync(
        TContext context,
        IReadOnlyList<TrackedOperation> tracked,
        bool insertWhenUpdateMissing,
        CancellationToken cancellationToken
    )
    {
        while (true)
        {
            try
            {
                return await context.SaveChangesAsync(cancellationToken);
            }
            catch (DbUpdateConcurrencyException ex)
            {
                // 更新対象が存在しない（他ユーザーの削除等）。方針に応じて INSERT へ切替、または競合として通知する
                if (
                    insertWhenUpdateMissing
                    && ex.Entries.Count > 0
                    && ex.Entries.All(entry => entry.State == EntityState.Modified)
                )
                {
                    foreach (var entry in ex.Entries)
                    {
                        entry.State = EntityState.Added;

                        // 再試行で INSERT へ切り替えたノードは、After 発火時の操作も Insert に更新する（Before は Update で発火済み）
                        foreach (var op in tracked)
                        {
                            if (ReferenceEquals(op.Entry.Entity, entry.Entity))
                            {
                                op.Operation = SaveOperation.Insert;
                            }
                        }
                    }

                    continue;
                }

                var conflict = ex.Entries.Count > 0 ? ex.Entries[0].Entity : null;
                var description =
                    conflict is null
                        ? "対象不明"
                        : $"{conflict.GetType().Name}、キー {EntitySaveMetadata.For(conflict.GetType()).KeyProperty.GetValue(conflict)}";
                throw new SaveConflictException(
                    $"更新対象のレコードが見つかりませんでした（{description}）。他のユーザーに削除または変更された可能性があります。"
                );
            }
        }
    }
}

/// <summary>Save フックの After に渡す、保存中の DbContext（＋その CurrentTransaction）に参加する EF Core コンテキスト</summary>
/// <remarks>
/// <para>
/// 生 SQL（<see cref="ExecuteSqlAsync"/>）は保存中 context の接続と現在のトランザクションで実行する
/// （EfCoreSqlExecutor と同じ束縛ヘルパー <see cref="RawSqlMapper.BindParameters"/> を流用する）。別接続・別トランザクションは張らない。
/// </para>
/// <para>
/// 除外列バイナリの書き込み（<see cref="WriteBinaryColumnAsync"/>）は、EF Core が方言固有のストリーミングを持てないため
/// <see cref="NotSupportedException"/> を投げる（Stream アクセサの EF Core 方針と同じ）。同一トランザクションで列を更新したい場合は
/// <see cref="ExecuteSqlAsync"/> を使うか、QuickER 版 Repository を利用する。
/// </para>
/// </remarks>
internal sealed class EfCoreSaveHookContext(DbContext context) : ISaveHookContext
{
    private readonly DbContext _context = context;

    /// <summary>保存中トランザクション内で生 SQL（任意 DML）を実行し、影響行数を返す（束縛は RawSqlMapper と 1 系統）</summary>
    public async Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        // 接続は保存中の DbContext が所有しており、既にトランザクションで開いている
        var connection = _context.Database.GetDbConnection();

        await using var command = connection.CreateCommand();
        command.CommandText = sql;
        // 進行中の保存トランザクションに参加する（別接続・別トランザクションを張らない）
        command.Transaction = _context.Database.CurrentTransaction?.GetDbTransaction();
        RawSqlMapper.BindParameters(command, parameters);
        return await command.ExecuteNonQueryAsync(cancellationToken);
    }

    /// <summary>EF Core モードでは除外列バイナリの書き込みは非対応（Stream アクセサと同方針＝生 SQL か QuickER 版 Repository を使う）</summary>
    public Task<bool> WriteBinaryColumnAsync(
        string propertyName,
        object key,
        Stream? source,
        long? length = null,
        CancellationToken cancellationToken = default
    ) =>
        throw new NotSupportedException(
            "EF Core モードでは Save フックの除外列バイナリ書き込み（WriteBinaryColumnAsync）は使用できません。"
                + "生 SQL（ExecuteSqlAsync）で更新するか、QuickER 版 Repository を使ってください。"
        );
}

/// <summary>生成された EF Core 版リポジトリ群を DI コンテナへ登録する拡張</summary>
public static class GeneratedEfCoreRepositoryServiceCollectionExtensions
{
    /// <summary>DbContext 構成とともに、生成された EF Core 版の全リポジトリを DI コンテナへ登録する</summary>
    /// <remarks>
    /// 既存の <c>AddGeneratedSqlServerRepositories</c> / <c>AddGeneratedSqliteRepositories</c> と同じインターフェイスへ
    /// EF Core 版実装を登録するため、呼び出しの差し替えだけでQuickER 版 Repository ⇔ EF Core（方言はアプリ側の構成で選択）を切り替えられる。
    /// </remarks>
    /// <param name="services">登録先のサービスコレクション</param>
    /// <param name="configureDbContext">方言プロバイダ・接続文字列の構成（例: <c>options => options.UseSqlServer(...)</c>）</param>
    public static IServiceCollection AddGeneratedEfCoreRepositories(
        this IServiceCollection services,
        Action<DbContextOptionsBuilder> configureDbContext
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(configureDbContext);

        services.AddDbContextFactory<QuickErDbContext>(configureDbContext);
        services.AddSingleton<ISqlExecutor, EfCoreSqlExecutor<QuickErDbContext>>();

        // Save フックのレジストリを既定登録する（ISaveHook<T> の登録が無ければ完全 no-op）
        services.TryAddScoped<ISaveHookRegistry>(provider => new ServiceProviderSaveHookRegistry(
            provider
        ));
        services.AddScoped<IDocumentRepository, EfCoreDocumentRepository>();
        services.AddScoped<IDocumentRemoteRepository>(provider =>
            provider.GetRequiredService<IDocumentRepository>()
        );
        services.AddScoped<IDocumentNoteRepository, EfCoreDocumentNoteRepository>();
        services.AddScoped<IDocumentNoteRemoteRepository>(provider =>
            provider.GetRequiredService<IDocumentNoteRepository>()
        );

        return services;
    }
}

/// <summary>DocumentEntity 用リポジトリの EF Core 版実装</summary>
public sealed partial class EfCoreDocumentRepository(
    IDbContextFactory<QuickErDbContext> contextFactory,
    ISaveHookRegistry? saveHooks = null
) : EfCoreRepository<DocumentEntity, int, QuickErDbContext>(
        contextFactory,
        saveHooks
    ),
        IDocumentRepository
{
    /// <summary>文書 ID と本体バイナリ（除外列 payload）を射影で取得する（文書 ID 昇順）</summary>
    public Task<IReadOnlyList<DocumentPayloadRow>> GetPayloadsAsync(CancellationToken cancellationToken = default) =>
        Query().OrderBy(e => e.DocumentId).ToProjectionListAsync(e => new DocumentPayloadRow { DocumentId = e.DocumentId, Payload = e.Payload }, cancellationToken);

    /// <summary>タイトル完全一致で文書を取得する（除外列 payload は取得されない）</summary>
    public Task<IReadOnlyList<DocumentEntity>> GetByTitleAsync(string title, CancellationToken cancellationToken = default) =>
        Query().Where(e => e.Title == title).ToListAsync(cancellationToken);

    /// <summary>本体バイナリ（payload）が存在する文書の件数を取得する</summary>
    public Task<int> CountWithPayloadAsync(CancellationToken cancellationToken = default) =>
        Query().Where(e => e.Payload != null).CountAsync(cancellationToken);

    /// <inheritdoc />
    public Task<bool> ReadPayloadAsync(int id, Stream destination, CancellationToken cancellationToken = default) =>
        throw new NotSupportedException(
            "EF Core モードでは Stream アクセサ（無制限バイナリ列の読み書き）は使用できません。QuickER 版 Repository を使うか、partial クラスで実装してください。"
        );

    /// <inheritdoc />
    public Task<bool> WritePayloadAsync(int id, Stream? source, long? length = null, CancellationToken cancellationToken = default) =>
        throw new NotSupportedException(
            "EF Core モードでは Stream アクセサ（無制限バイナリ列の読み書き）は使用できません。QuickER 版 Repository を使うか、partial クラスで実装してください。"
        );

    /// <inheritdoc />
    public Task<bool> ReadThumbAsync(int id, Stream destination, CancellationToken cancellationToken = default) =>
        throw new NotSupportedException(
            "EF Core モードでは Stream アクセサ（無制限バイナリ列の読み書き）は使用できません。QuickER 版 Repository を使うか、partial クラスで実装してください。"
        );

    /// <inheritdoc />
    public Task<bool> WriteThumbAsync(int id, Stream? source, long? length = null, CancellationToken cancellationToken = default) =>
        throw new NotSupportedException(
            "EF Core モードでは Stream アクセサ（無制限バイナリ列の読み書き）は使用できません。QuickER 版 Repository を使うか、partial クラスで実装してください。"
        );
}

